int CashHackSpecialPower::findAmountToSteal() const
{
    const CashHackSpecialPowerModuleData *data=getCashHackSpecialPowerModuleData();
    Player *owner=getObject()->getControllingPlayer();
    if(owner) {
        for(const CashHackSpecialPowerModuleData::Upgrades *p=data->m_upgrades.begin();p!=data->m_upgrades.end();++p)
            if(owner->hasScience(p->m_science)) return p->m_amountToSteal;
    }
    return data->m_defaultAmountToSteal;
}
